        if (i % 1000000 == 0)
        {
            printf("%07d elements, inserting a value takes %1.5e s/op\n", bostree_node_count(tree), gestime / 1e9);
            test_tree_sanity(tree);
            printf(" sanity check passed\n");
            gestime = 0;
        }
    }
    float selecttime = 0;
    float deletetime = 0;
    for (; i > 0; i--)
    {
        int w = rand() * i / 2147483647;
        ftime(&t1);
        BOSNode *node = bostree_select(tree, w);
        ftime(&t2);
        selecttime += (t2.time - t1.time) * 1000 + t2.millitm - t1.millitm;
        if (!node)
        {
            printf("Node missing!\n");
            test_tree_sanity(tree);
            exit(1);
        }
        ftime(&t1);
        bostree_remove(tree, node);
        ftime(&t2);
        deletetime += (t2.time - t1.time) * 1000 + t2.millitm - t1.millitm;
        if (i % 1000000 == 0)
        {
            printf("%07d elements, selecting a value takes %1.5e s/op, removing a value takes %1.5e s/op\n",
                   bostree_node_count(tree), selecttime / 1e9, deletetime / 1e9);
            test_tree_sanity(tree);
            printf(" sanity check passed\n");
            selecttime = 0;
            deletetime = 0;
        }
    }
    return 0;
}
